// BL 以外のテーマの参考例文（ショット）と場面。
//
// 出典は Thai PBS の人手字幕（[CC]）のうち、話者記号の付いた会話行。
// 食べ物は「Foodwork」108回分。ほかはシットコム「มันนี่ที่รัก」88回分と、
// 市場・旅行・交通などを扱う回の字幕から、Jev でテーマと場面に振り分けた行を選んだ。
// 仕事は「ดูให้รู้ Dohiru」の仕事回16本と「มันนี่ที่รัก」99回分の職場の行を足した。
// 仕事・食べ物以外は、短編映画「The Ghost Studio」82本のタイ語字幕と Thai PBS [CC]
// 約390本（食・工芸・旅など）の会話行から、手で選んで足した。乱暴な人称（มึง・กู）・
// 方言・怪談に特有の行は採らない。
// 学校・家族・趣味などは、Thai PBS ドラマ（ครูมะ・Sweet Sensory・บุษบาลุยไฟ 等）の
// 予告・抜粋の YouTube 自動字幕からも足した。自動字幕は語の区切りを直した文で、
// 元の字幕と8割以上一致する文だけを残している。
// ショットは字幕の文そのまま。番組名・人物名・注釈は入れない（人名を含む行は採らない）。
// 例外として、人名だけを消した行と、綴りの崩れ（หรอ→เหรอ、人称の เค้า→เขา・เรา 等）を直した行がある。
// 例外として、華人系家庭の呼び方（ป๊า・เจ๊）は一般的な พ่อ・พี่ に書き換えた。
// 話者が男性に偏っていたため、女性が言っても自然な行（Jev で判定）の一部を
// ครับ→ค่ะ/คะ、ผม→ฉัน に書き換え、テーマごとに男女をおおむね揃えた。
// 推し活は、ファンの vlog・ポッドキャストの音声を Cloud Speech-to-Text（Chirp）で文字起こしした行と、
// Wisesight Sentiment コーパス（CC0）の SNS 投稿から選んだ。言いよどみ・繰り返しを詰めた行、
// YouTube 自動字幕で見つけた行を Chirp で聞き直して直した行がある。
// 韓国の歌手のファンの行は、タイの俳優のファンにも通じるよう韓国・K-POP の語を書き換えた
// （คอนเกาหลี→คอน、คัมแบ็ก→เปิดกล้องเรื่องใหม่ 等）。
// タイ暮らし・タイ旅行の7テーマ（食べ物・家族・健康・交通・買い物・天気・旅行）には、
// 具体的な状況（shotSituation）のエピソードを Codex に時系列の会話で書かせ、1行ごとに場面を
// 振った行がある（約1500文）。それより前に場面名だけを渡して Codex に書かせた行は、学習語を
// 入れ込んだ説明調の文（รสเปรี้ยวเกิดขึ้นตอนเคี้ยวมะนาว 等）や品名と数を差し替えただけの型に
// 偏っていたので、1行ずつ判定して説明調・型の行を外し、単独で意味の通らない行を直した。
// 旅行には、旅の連れとの雑談（場面名に「（旅の雑談）」）、旅先での交流（「（旅先の交流）」）、
// 旅のトラブル（「（旅のトラブル）」）のエピソードも足した。既存の場面に混ぜると重心がずれて
// 付いていた語が外れるので、場面名で分けている。直しの行は、語を1か所に足しただけのものを採り、
// 言い換え・2か所以上の足しは行ごと外した。恋愛にもエピソードの行がある。
// 文を足したら scripts/build_shot_embeddings.py を流して GCS に上げる（場面の選出に使う）。
